import math

def eval_x6(d):
    lq = -math.pi * math.sqrt(2.0 * d / 3.0)   # log(q), q = exp(-2*pi*sqrt(d/6))
    q = math.exp(lq)
    N = int(40.0 / (-lq)) + 1                  # q^N ~ e^-40: beyond this everything negligible

    # S(k) = sum_{M>=1} sigma1(M) * q^(kM), so
    # EcS = sum_M sigma1(M) * (q^M - 2 q^(2M) + 3 q^(3M) - 6 q^(6M))
    sig = [0] * (N + 1)
    for i in range(1, N + 1):
        for j in range(i, N + 1, i):
            sig[j] += i

    EcS = 0.0
    p = q
    for m in range(1, N + 1):
        c = 1.0
        if m % 2 == 0:
            c -= 2.0
        if m % 3 == 0:
            c += 3.0
        if m % 6 == 0:
            c -= 6.0
        EcS += sig[m] * c * p
        p *= q

    # log W6 = lq/2 + sum_m a_m * log1p(-q^m), a_m = #{k in {1,2,3,6} : k | m}
    lw = 0.5 * lq
    p = q
    log1p = math.log1p
    for m in range(1, N + 1):
        a = 1
        if m % 2 == 0:
            a += 1
        if m % 3 == 0:
            a += 1
        if m % 6 == 0:
            a += 1
        for _ in range(a):
            lw += log1p(-p)
        p *= q

    return (4.0 + 24.0 * EcS) / (4.0 * math.exp(lw)) + 2.0
